    rows = ",\n".join("('%s','%s')" % (k, v.replace("'", "''")) for k, v in sorted(HI.items()))
    sql = ("create table if not exists public.station_hi (code text primary key, name_hi text not null);\n"
           "alter table public.station_hi enable row level security;\n"
           "drop policy if exists \"anyone reads hindi names\" on public.station_hi;\n"
           "create policy \"anyone reads hindi names\" on public.station_hi for select to anon, authenticated using (true);\n"
           "grant select on public.station_hi to anon, authenticated;\n"
           "insert into public.station_hi (code, name_hi) values\n" + rows +
           "\non conflict (code) do update set name_hi = excluded.name_hi;\n")
    open(__file__.replace(".py", ".sql"), "w").write(sql)
    print(len(HI))
